  LinearLayout find=new LinearLayout(this);search=new EditText(this);search.setSingleLine(true);search.setTextSize(15);search.setTextColor(Color.WHITE);search.setHintTextColor(0xffd4b9c1);search.setHint(tr("Поиск видео в YouTube","Search YouTube"));search.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);search.setBackground(shape(0xe72a2032));search.setPadding(dp(12),0,dp(6),0);search.setOnEditorActionListener((v,a,e)->{if(a==android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH){search();return true;}return false;});find.addView(search,new LinearLayout.LayoutParams(0,dp(46),1));find.addView(key("⌕",this::search),new LinearLayout.LayoutParams(dp(48),dp(46)));root.addView(find);
  status=new TextView(this);status.setTextSize(11);status.setTextColor(Notices.prefs(this).getString("theme","dark").equals("light")?0xff612439:0xffffb9cd);status.setPadding(dp(8),dp(7),dp(8),dp(7));status.setOnClickListener(v->information());root.addView(status);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(100);root.addView(progress,new LinearLayout.LayoutParams(-1,dp(3)));content=new FrameLayout(this);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));createWeb();if(state!=null)loaded=web.restoreState(state)!=null;if(!loaded)ui.post(this::choose);
